sql.if:
AND ( EXISTS (SELECT 1 FROM hobby h WHERE h.board_id = p.board_id AND h.use_yn = 'Y') OR EXISTS ( SELECT 1 FROM menu m JOIN auth a ON a.menu_id = m.menu_id AND a.type = 'GRP' AND a.menu_yn = 'Y' AND a.use_yn = 'Y'
JOIN auth_member au ON au.auth_group_id = a.conn_id AND au.use_yn = 'Y' AND au.member_id = #{memberId}
WHERE m.area = 'GEN' AND m.use_yn = 'Y' AND m.conn_cd = 'MENU02' AND m.conn_id = p.board_id AND a.conn_id = 'GUEST' ) )
